/**
 * Helpers for the sample reports generated by the Graylum positioning Skill (fictional people; the full texts sit in
 * the JSON files next to this one, sanitized: no @handles, no links, benchmarks as 对标账号 A/B/C). Every report has
 * the same order: 一句话结论, then chapters 一 to 十三; this splits one into those 14 chapters.
 */
export type ReportChapterText = { heading: string; markdown: string };

/** The page's chapter titles, in report order (the real report's 13 chapters and 一句话结论). */
export const REPORT_CHAPTER_TITLES = [
  '一句话结论', '1 现状盘点', '2 目标和可行性', '3 受众', '4 平台选择', '5 对标账号分析', '6 账号定位', '7 账号三件套',
  '8 内容规划', '9 运营手册', '10 变现路径', '11 合规提醒', '12 见效时间', '13 待验证的假设',
] as const;

/** The report's title line ("# …") and its 14 chapters ("## …" sections), each without its heading line. */
export function splitReport(markdown: string): { title: string; chapters: ReportChapterText[] } {
  const title = /^# (.+)$/m.exec(markdown)?.[1]?.trim() ?? '';
  const parts = markdown.split(/^## /m).slice(1);
  const chapters = parts.map(part => {
    const [heading, ...rest] = part.split('\n');
    return { heading: heading.trim(), markdown: rest.join('\n').trim() };
  });
  return { title, chapters };
}

/**
 * A chapter as plain prose, for places that show text without Markdown (the jury's result page): bold, heading and
 * quote marks dropped, list marks kept as "·", a table as one line per row ("a：b；c"), separator rows dropped.
 */
export function plainText(markdown: string): string {
  return markdown.split('\n').map(line => {
    const row = line.trim();
    if (/^\|?\s*:?-{2,}/.test(row)) return null;
    if (row.startsWith('|')) {
      const cells = row.replace(/^\||\|$/g, '').split('|').map(cell => cell.trim()).filter(Boolean);
      return cells.length > 1 ? `${cells[0]}：${cells.slice(1).join('；')}` : cells[0] ?? '';
    }
    return row.replace(/^>\s?/, '').replace(/^#{1,6}\s+/, '').replace(/^[-*]\s+/, '· ');
  }).filter((line): line is string => line !== null).join('\n').replace(/\*\*|__/g, '').replace(/\n{3,}/g, '\n\n').trim();
}
